const SOURCES={unemployment:{title:'Giải quyết hưởng trợ cấp thất nghiệp - Mã thủ tục 1.001978',agency:'Cổng Dịch vụ công Bộ Nội vụ',updated:'Tra cứu 2026',url:'https://dichvucong.moha.gov.vn/VdxpTTHCOnlineDetail.aspx?DocId=89'},unemploymentLaw:{title:'Luật Việc làm số 74/2025/QH15',agency:'Cổng Thông tin điện tử Chính phủ',updated:'Hiệu lực 01/01/2026',url:'https://vanban.chinhphu.vn/?docid=214560&pageid=27160'},training:{title:'Hỗ trợ đào tạo nghề cho người đang nhận trợ cấp thất nghiệp',agency:'Cổng TTĐT Chính phủ',updated:'28/05/2026',url:'https://www2.en.baochinhphu.vn/chinh-sach-ho-tro-dao-tao-nghe-cho-nguoi-dang-nhan-tro-cap-that-nghiep-102260528145755317.htm'},birth:{title:'Đăng ký khai sinh và cấp thẻ BHYT cho trẻ dưới 6 tuổi',agency:'Cổng Dịch vụ công Quốc gia',updated:'Tra cứu 2026',url:'https://dichvucong.gov.vn/p/home/dvc-tthc-thu-tuc-hanh-chinh-chi-tiet.html?ma_thu_tuc=10434'},linkedBirth:{title:'Liên thông khai sinh, thường trú và BHYT cho trẻ dưới 6 tuổi',agency:'Cổng TTĐT Chính phủ',updated:'11/01/2024',url:'https://baochinhphu.vn/lien-thong-cac-tthc-dang-ky-khai-sinh-dang-ky-thuong-tru-cap-the-bao-hiem-y-te-cho-tre-duoi-6-tuoi-102240111171423772.htm'},maternity:{title:'Luật Bảo hiểm xã hội 2024 - chế độ thai sản',agency:'Bảo hiểm xã hội Việt Nam',updated:'Hiệu lực từ 2025',url:'https://lamdong.baohiemxahoi.gov.vn/content/tintuc/Lists/News/Attachments/16047/LU%E1%BA%ACT%20BHXH%202024.pdf'},business:{title:'Đăng ký hộ kinh doanh',agency:'Cổng Dịch vụ công Quốc gia',updated:'Cần xác nhận theo địa phương',url:'https://dichvucong.gov.vn/'},food:{title:'Thủ tục an toàn thực phẩm',agency:'Cổng Dịch vụ công Quốc gia',updated:'Cần xác nhận theo mô hình',url:'https://dichvucong.gov.vn/'}};
const BASE={view:'start',journey:'job',prompt:'',step:1,profile:{location:'Đà Nẵng',dependants:1,terminationDate:'2026-06-25',lawfulTermination:'yes',insuranceMonths:18,newJob:'no',avgSalary:12000000,pregnant:'yes',birthDate:'2026-08-20',birthCertificate:'yes',married:'yes',maternityMonths:8,venueReady:'yes',employees:4,servesAlcohol:'no'},consent:{identity:true,employment:true,insurance:true,finance:false},tasks:{},documents:{},rescue:null,createdAt:null};
let state=load();function cloneBase(){return JSON.parse(JSON.stringify(BASE))}function load(){try{return Object.assign(cloneBase(),JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return cloneBase()}}function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function view(id){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+id).classList.add('active');state.view=id.replace('-view','');save();scrollTo(0,0)}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>e.classList.remove('show'),2400)}
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n),dateVN=v=>new Intl.DateTimeFormat('vi-VN').format(new Date(v+'T00:00:00')),dateObjVN=d=>new Intl.DateTimeFormat('vi-VN').format(d),help=t=>`<span class="help-tip" tabindex="0" aria-label="${t}" data-tip="${t}">?</span>`;
function plusMonths(v,n){const d=new Date(v+'T12:00:00');d.setMonth(d.getMonth()+n);return d}function daysUntil(d){return Math.ceil((d-new Date())/86400000)}
function detect(s){s=s.toLowerCase();if(/sinh|em bé|khai sinh|thai sản/.test(s)&&!/mất việc|nghỉ việc|thất nghiệp/.test(s))return'baby';if(/quán|nhà hàng|kinh doanh|cửa hàng|restaurant/.test(s))return'business';return'job'}
function meta(){return{job:{title:'Hỗ trợ sau khi mất việc',event:'Mất việc và ổn định cuộc sống'},baby:{title:'Chào đón thành viên mới',event:'Sinh con và hoàn tất giấy tờ'},business:{title:'Mở quán ăn nhỏ',event:'Khởi sự hộ kinh doanh'}}[state.journey]}
function tasks(){if(state.journey==='job'){const deadline=plusMonths(state.profile.terminationDate,3),left=daysUntil(deadline),loc=state.profile.location||'địa phương của bạn';return[{id:'confirm-termination-date',title:'Kiểm tra ngày chấm dứt việc làm',detail:`Đối chiếu ngày ${dateVN(state.profile.terminationDate)} với quyết định thôi việc hoặc hợp đồng đã chấm dứt. Ngày này được dùng để tính hạn dự kiến ${dateObjVN(deadline)}.`,due:'Làm ngay',urgent:left<=10,source:'unemployment',help:'Mở giấy tờ chấm dứt việc làm và kiểm tra ngày có hiệu lực. Nếu khác ngày đã nhập, hãy tạo lại LifeCase với ngày chính xác.'},{id:'verify-insurance',title:'Đối chiếu quá trình đóng BHTN',detail:`Kiểm tra ${state.profile.insuranceMonths} tháng đã khai với dữ liệu BHXH/VssID hoặc xác nhận của cơ quan BHXH.`,due:'Bước 2',source:'unemployment',help:'BHTN là bảo hiểm thất nghiệp. Trong hệ thống thật, bước này có thể tự động nếu người dân đồng ý kết nối dữ liệu BHXH.'},{id:'termination-doc',title:'Chuẩn bị giấy tờ chấm dứt việc làm',detail:'Tải quyết định thôi việc, hợp đồng đã hết hạn hoặc tài liệu tương đương được thủ tục chính thức chấp nhận.',due:'Bước 3',source:'unemployment',help:'Vào mục Giấy tờ để xem yêu cầu, tải tệp và nhận báo cáo sẵn sàng.'},{id:'prepare-application',title:'Chuẩn bị đề nghị hưởng trợ cấp thất nghiệp',detail:'Mở thủ tục chính thức, tải đúng mẫu hiện hành và điền thông tin đã có trong LifeCase.',due:'Bước 4',source:'unemployment',help:'LifePath không tự tạo mẫu pháp lý mới. Hệ thống dẫn đến mẫu do cơ quan có thẩm quyền công bố.'},{id:'review-dossier',title:'Kiểm tra bộ hồ sơ trước khi nộp',detail:'Xử lý mọi giấy tờ còn thiếu hoặc có cảnh báo trong Document Readiness.',due:'Bước 5',source:'unemployment',help:'Sẵn sàng để nộp không đồng nghĩa đã được cơ quan nhà nước phê duyệt.'},{id:'submit-unemployment',title:`Nộp tại Trung tâm Dịch vụ việc làm ${loc}`,detail:`Nộp trước ngày dự kiến ${dateObjVN(deadline)}. Mở trang thủ tục để kiểm tra địa chỉ và phương thức tiếp nhận hiện hành.`,due:left>=0?`${left} ngày`:'Có thể quá hạn',urgent:left<=10,source:'unemployment',help:'Nơi tiếp nhận là Trung tâm Dịch vụ việc làm tại địa phương người lao động muốn nhận trợ cấp; cần kiểm tra hướng dẫn đang có hiệu lực.'},{id:'track-result',title:'Theo dõi phiếu hẹn và kết quả',detail:'Lưu mã hồ sơ hoặc phiếu hẹn, theo dõi yêu cầu bổ sung và cập nhật LifeCase khi có kết quả.',due:'Sau khi nộp',source:'unemployment',help:'Nếu hồ sơ bị trả lại, dùng mục Hồ sơ bị trả lại để chuyển thông báo thành các việc cần sửa.'}]}
 if(state.journey==='baby')return[{id:'birth-register',title:'Đăng ký khai sinh',detail:'Hoàn thiện tờ khai và giấy chứng sinh.',due:'Bước đầu tiên',source:'birth'},{id:'residence-register',title:'Đăng ký thường trú cho trẻ',detail:'Thực hiện trong quy trình dịch vụ công liên thông.',due:'Liên thông',source:'linkedBirth'},{id:'health-card',title:'Cấp thẻ bảo hiểm y tế',detail:'Dữ liệu được chuyển trong quy trình liên thông.',due:'Liên thông',source:'birth'},{id:'maternity-claim',title:'Chuẩn bị hồ sơ chế độ thai sản',detail:'Đối chiếu thời gian tham gia bảo hiểm và giấy tờ sinh.',due:'Kiểm tra',source:'maternity'}];
 return[{id:'business-register',title:'Đăng ký hộ kinh doanh',detail:'Xác định tên, địa điểm, ngành nghề và chủ hộ.',due:'Bước đầu tiên',source:'business'},{id:'tax-setup',title:'Đăng ký thuế và hóa đơn điện tử',detail:'Thiết lập nghĩa vụ thuế phù hợp mô hình doanh thu.',due:'Sau đăng ký',source:'business'},{id:'food-safety',title:'Xác định yêu cầu an toàn thực phẩm',detail:'Kiểm tra loại giấy chứng nhận hoặc cam kết áp dụng.',due:'Trước khai trương',source:'food'},{id:'local-check',title:'Kiểm tra yêu cầu tại địa phương',detail:'Đối chiếu phòng cháy, biển hiệu và quy định địa điểm.',due:'Cần xác minh',source:'business'}]}
function docs(){if(state.journey==='job')return[{id:'id',title:'Căn cước / định danh',desc:'Xác minh người nộp hồ sơ',auto:state.consent.identity},{id:'termination',title:'Giấy tờ chấm dứt việc làm',desc:'Quyết định thôi việc hoặc tài liệu tương đương'},{id:'insurance',title:'Thông tin đóng bảo hiểm',desc:'Đối chiếu thời gian đóng BHTN',auto:state.consent.insurance},{id:'bank',title:'Tài khoản nhận trợ cấp',desc:'Thông tin thanh toán hợp lệ'}];if(state.journey==='baby')return[{id:'id',title:'Định danh cha/mẹ',desc:'Xác minh người yêu cầu',auto:state.consent.identity},{id:'birth-proof',title:'Giấy chứng sinh',desc:'Tài liệu từ cơ sở y tế'},{id:'marriage',title:'Giấy chứng nhận kết hôn',desc:'Khi dữ liệu chưa được chia sẻ'},{id:'health-form',title:'Tờ khai tham gia BHYT',desc:'Thông tin cấp thẻ cho trẻ'}];return[{id:'id',title:'Định danh chủ hộ',desc:'Xác minh người đăng ký',auto:state.consent.identity},{id:'venue',title:'Thông tin địa điểm',desc:'Địa chỉ và quyền sử dụng hợp pháp'},{id:'business-form',title:'Giấy đề nghị đăng ký hộ kinh doanh',desc:'Thông tin ngành nghề và vốn'},{id:'food-plan',title:'Hồ sơ an toàn thực phẩm',desc:'Tùy quy mô và hoạt động chế biến'}]}
function benefits(){if(state.journey==='job'){const p=state.profile,deadline=plusMonths(p.terminationDate,3),within=daysUntil(deadline)>=0,insured=+p.insuranceMonths>=12,lawful=p.lawfulTermination==='yes',jobless=p.newJob==='no',pass=[lawful,insured,within,jobless].filter(Boolean).length,months=Math.min(12,+p.insuranceMonths<=36?3:3+Math.floor((+p.insuranceMonths-36)/12)),amount=+p.avgSalary*.6,loc=p.location||'địa phương của bạn';return[{id:'unemployment',title:'Trợ cấp thất nghiệp',status:pass===4?'eligible':pass>=2?'review':'unavailable',confidence:pass/4,summary:pass===4?`Ước tính ${money(amount)}/tháng trong khoảng ${months} tháng, trước khi áp dụng mức trần.`:'Cần bổ sung hoặc điều chỉnh điều kiện trước khi có thể đánh giá.',result:`Nhận khoản trợ cấp hằng tháng nếu hồ sơ được cơ quan có thẩm quyền phê duyệt.`,requirements:['Đề nghị hưởng trợ cấp thất nghiệp theo mẫu hiện hành','Giấy tờ xác nhận chấm dứt hợp đồng hoặc việc làm','Thông tin quá trình đóng BHTN','Thông tin định danh và nhận kết quả theo yêu cầu thủ tục'],submission:`Trung tâm Dịch vụ việc làm ${loc}. Mở thủ tục chính thức để kiểm tra địa chỉ và phương thức tiếp nhận.`,dependency:'Không phụ thuộc quyền lợi khác. Đây là mục tiêu chính của LifeCase.',next:'Mở kế hoạch để hoàn tất 7 bước',reasons:[{ok:lawful,text:'Chấm dứt việc làm đúng quy định'},{ok:insured,text:`Đã khai đóng BHTN ${p.insuranceMonths} tháng`},{ok:within,text:`Hạn dự kiến: ${dateVN(deadline.toISOString().slice(0,10))}`},{ok:jobless,text:'Chưa có việc làm thuộc diện BHXH bắt buộc'}],source:'unemployment'},{id:'health',title:'BHYT trong thời gian hưởng trợ cấp',status:pass===4?'eligible':'review',confidence:pass===4?1:.5,summary:'Quyền lợi phụ thuộc vào quyết định hưởng trợ cấp thất nghiệp; không phải một bộ hồ sơ độc lập trong LifeCase này.',result:'Duy trì quyền lợi khám chữa bệnh BHYT trong thời gian hưởng trợ cấp theo quy định.',requirements:['Hoàn tất và được phê duyệt trợ cấp thất nghiệp','Kiểm tra trạng thái thẻ trên VNeID/VssID sau khi có quyết định'],submission:'Không cần nộp một hồ sơ BHYT riêng ở bước này; hệ thống thật sẽ theo dõi trạng thái sau quyết định trợ cấp.',dependency:'Chờ quyền lợi Trợ cấp thất nghiệp được phê duyệt.',next:'Hoàn tất hồ sơ trợ cấp thất nghiệp trước',reasons:[{ok:pass===4,text:'Có khả năng đáp ứng điều kiện trợ cấp thất nghiệp'},{ok:state.consent.insurance,text:'Đã cho phép đối chiếu dữ liệu bảo hiểm'}],source:'unemployment'},{id:'training',title:'Hỗ trợ đào tạo, nâng cao kỹ năng nghề',status:insured?'eligible':'review',confidence:insured?.8:.4,summary:'Có thể đăng ký hỗ trợ học nghề nếu có nhu cầu và đáp ứng điều kiện hiện hành.',result:'Được xem xét hỗ trợ chi phí một khóa đào tạo tại cơ sở đủ điều kiện.',requirements:['Xác định nghề hoặc khóa học mong muốn','Chọn cơ sở đào tạo đủ điều kiện','Nộp đề nghị theo hướng dẫn của Trung tâm Dịch vụ việc làm'],submission:`Liên hệ Trung tâm Dịch vụ việc làm ${loc} để được tư vấn khóa học và hồ sơ hiện hành.`,dependency:'Có thể thực hiện song song sau khi đã xác minh quá trình BHTN.',next:'Chọn nhu cầu học nghề',reasons:[{ok:insured,text:'Có quá trình tham gia BHTN'},{ok:false,text:'Chưa chọn khóa học và cơ sở đào tạo'}],source:'training'},{id:'maternity-check',title:'Kiểm tra khả năng hưởng chế độ thai sản',status:p.pregnant==='yes'?'review':'unavailable',confidence:p.pregnant==='yes'?.35:0,summary:'Đang mang thai là tín hiệu để kiểm tra thêm, chưa đủ để kết luận quyền lợi.',result:'Nếu đáp ứng điều kiện đóng BHXH trong giai đoạn tham chiếu, người dùng có thể được xem xét chế độ thai sản khi sinh con.',requirements:['Ngày dự sinh','Quá trình đóng BHXH trong giai đoạn trước sinh','Tình trạng tham gia BHXH tại thời điểm nghỉ việc'],submission:'LifePath sẽ tạo một hành trình thai sản riêng sau khi có ngày dự sinh và dữ liệu BHXH cần thiết.',dependency:'Cần thêm thông tin; không làm chậm hồ sơ trợ cấp thất nghiệp.',next:'Bổ sung ngày dự sinh và dữ liệu BHXH',reasons:[{ok:p.pregnant==='yes',text:'Đã khai đang mang thai'},{ok:false,text:'Chưa có ngày dự sinh và giai đoạn đóng BHXH cần kiểm tra'}],source:'maternity'},{id:'family',title:'Sàng lọc hỗ trợ theo hoàn cảnh gia đình',status:'review',confidence:state.consent.finance?.55:.2,summary:state.consent.finance?'Có thể đối chiếu chính sách địa phương phụ thuộc thu nhập.':'Cần đồng ý sử dụng bối cảnh thu nhập nếu muốn sàng lọc thêm.',result:'Phát hiện các hỗ trợ địa phương có thể phù hợp với thu nhập và người phụ thuộc.',requirements:['Địa phương cư trú','Số người phụ thuộc','Bối cảnh thu nhập được chia sẻ tự nguyện'],submission:'Phụ thuộc chính sách địa phương; LifePath chỉ hiển thị khi có nguồn và kênh tiếp nhận xác định.',dependency:'Tùy chọn, không ảnh hưởng mục tiêu chính.',next:'Cấp consent tài chính nếu muốn kiểm tra',reasons:[{ok:+p.dependants>0,text:`Có ${p.dependants} người phụ thuộc`},{ok:state.consent.finance,text:'Đã cho phép sử dụng bối cảnh tài chính'}],source:null}]}
 if(state.journey==='baby')return[{id:'birth',title:'Khai sinh và cấp thẻ BHYT liên thông',status:'eligible',confidence:1,summary:'Có thể thực hiện nhóm thủ tục liên thông, giảm khai lại thông tin giữa các cơ quan.',reasons:[{ok:true,text:'Có sự kiện sinh con'},{ok:state.profile.birthCertificate==='yes',text:'Có giấy chứng sinh'}],source:'linkedBirth'},{id:'maternity',title:'Chế độ hoặc trợ cấp thai sản',status:+state.profile.maternityMonths>=6?'eligible':'review',confidence:+state.profile.maternityMonths>=6?.85:.4,summary:'Kết quả phụ thuộc hình thức tham gia BHXH và thời gian đóng trong giai đoạn trước sinh.',reasons:[{ok:+state.profile.maternityMonths>=6,text:`Đã khai ${state.profile.maternityMonths} tháng tham gia trong 12 tháng trước sinh`},{ok:state.consent.insurance,text:'Đã cho phép đối chiếu dữ liệu bảo hiểm'}],source:'maternity'}];
 return[{id:'registration',title:'Đăng ký hộ kinh doanh',status:'eligible',confidence:.9,summary:'Đã xác định luồng đăng ký cơ bản; thẩm quyền và yêu cầu chi tiết cần đối chiếu địa phương.',reasons:[{ok:true,text:'Đã xác định chủ hộ và địa phương'},{ok:state.profile.venueReady==='yes',text:'Đã có địa điểm dự kiến'}],source:'business'},{id:'food',title:'Yêu cầu an toàn thực phẩm',status:'review',confidence:.55,summary:'Nghĩa vụ cụ thể phụ thuộc hoạt động chế biến, quy mô và mô hình phục vụ.',reasons:[{ok:true,text:'Có hoạt động kinh doanh ăn uống'},{ok:false,text:'Cần xác minh mặt bằng và quy trình chế biến'}],source:'food'}]}
function readiness(){const ds=docs(),ready=ds.filter(d=>d.auto||state.documents[d.id]).length,done=tasks().filter(t=>state.tasks[t.id]).length;return Math.round((ready/ds.length*.65+done/tasks().length*.35)*100)}
function renderIntake(){const m=meta();$('#intake-step-label').textContent=`Bước ${state.step}/3`;$('#intake-progress-bar').style.width=`${state.step*33.33}%`;const root=$('#intake-content');root.innerHTML=state.step===1?profileForm(m):state.step===2?consentForm():analysis(m);bindIntake();if(state.step===3)setTimeout(()=>{state.createdAt=state.createdAt||new Date().toISOString();save();openApp()},1500)}
function profileForm(m){let f;if(state.journey==='job')f=`<div class="field"><label>Ngày chấm dứt việc làm</label><input name="terminationDate" type="date" value="${state.profile.terminationDate}" required></div><div class="field"><label>Nơi cư trú hiện tại</label><input name="location" value="${state.profile.location}" required></div><div class="field"><label>Số tháng đã đóng BHTN trong 24 tháng gần nhất</label><input name="insuranceMonths" type="number" min="0" max="120" value="${state.profile.insuranceMonths}" required></div><div class="field"><label>Lương bình quân đóng BHTN 6 tháng gần nhất</label><input name="avgSalary" type="number" min="0" value="${state.profile.avgSalary}" required><small>Ước tính chưa áp dụng mức trần vùng.</small></div><div class="field"><label>Việc làm chấm dứt đúng quy định?</label><select name="lawfulTermination"><option value="yes" ${state.profile.lawfulTermination==='yes'?'selected':''}>Có</option><option value="no" ${state.profile.lawfulTermination==='no'?'selected':''}>Không / chưa chắc chắn</option></select></div><div class="field"><label>Đã có việc làm mới thuộc diện BHXH bắt buộc?</label><select name="newJob"><option value="no" ${state.profile.newJob==='no'?'selected':''}>Chưa</option><option value="yes" ${state.profile.newJob==='yes'?'selected':''}>Đã có</option></select></div><div class="field"><label>Số người phụ thuộc</label><input name="dependants" type="number" min="0" value="${state.profile.dependants}"></div><div class="field"><label>Đang mang thai?</label><select name="pregnant"><option value="no">Không</option><option value="yes" ${state.profile.pregnant==='yes'?'selected':''}>Có</option></select></div>`;else if(state.journey==='baby')f=`<div class="field"><label>Ngày sinh của trẻ</label><input name="birthDate" type="date" value="${state.profile.birthDate}" required></div><div class="field"><label>Nơi cư trú</label><input name="location" value="${state.profile.location}" required></div><div class="field"><label>Đã có giấy chứng sinh?</label><select name="birthCertificate"><option value="yes">Đã có</option><option value="no">Chưa có</option></select></div><div class="field"><label>Cha mẹ đã đăng ký kết hôn?</label><select name="married"><option value="yes">Có</option><option value="no">Không / trường hợp khác</option></select></div><div class="field full-field"><label>Số tháng tham gia BHXH trong 12 tháng trước sinh</label><input name="maternityMonths" type="number" min="0" max="12" value="${state.profile.maternityMonths}"></div>`;else f=`<div class="field"><label>Tỉnh/thành phố dự kiến kinh doanh</label><input name="location" value="${state.profile.location}" required></div><div class="field"><label>Đã có địa điểm kinh doanh?</label><select name="venueReady"><option value="yes">Đã có</option><option value="no">Đang tìm</option></select></div><div class="field"><label>Số người dự kiến làm việc</label><input name="employees" type="number" min="1" value="${state.profile.employees}"></div><div class="field"><label>Có phục vụ đồ uống có cồn?</label><select name="servesAlcohol"><option value="no">Không</option><option value="yes">Có</option></select></div>`;return `<form id="profile-form" class="intake-card"><div class="detected-event"><small>LIFEPATH ĐÃ NHẬN DIỆN</small><strong>${m.event}</strong></div><h2>Cho chúng tôi biết thêm một chút</h2><p class="intro">Câu trả lời sẽ thay đổi kết quả và kế hoạch hành động.</p><div class="form-grid">${f}</div><div class="intake-actions"><button class="primary-button">Tiếp tục</button></div></form>`}
function consentForm(){const a=[['identity','Định danh cá nhân','Họ tên, số định danh và nơi cư trú.','Khi triển khai thật, LifePath chỉ yêu cầu các trường cần thiết qua VNeID hoặc nền tảng định danh được cấp phép.'],['employment','Việc làm','Tình trạng hợp đồng và thời điểm chấm dứt.','Dùng để xác định sự kiện mất việc và tính thời hạn.'],['insurance','Bảo hiểm xã hội','Quá trình tham gia để đánh giá quyền lợi.','Dùng để đối chiếu thời gian đóng BHXH/BHTN; không thay đổi dữ liệu gốc.'],['finance','Bối cảnh tài chính tùy chọn','Thu nhập và thuế để sàng lọc hỗ trợ; không dùng chấm điểm tín dụng.','Hoàn toàn tùy chọn và không ảnh hưởng hồ sơ trợ cấp thất nghiệp.']];return `<form id="consent-form" class="intake-card"><h2>Bạn kiểm soát dữ liệu của mình ${help('Consent là sự đồng ý có mục đích. Bạn có thể bật hoặc tắt từng nhóm dữ liệu trước khi LifePath phân tích.')}</h2><p class="intro">Bản demo dùng dữ liệu mô phỏng. Khi triển khai thật, hệ thống chỉ đọc đúng trường dữ liệu được bạn cho phép từ nguồn được phê duyệt; không tự động lấy toàn bộ dữ liệu VNeID.</p><div class="consent-list">${a.map(i=>`<div class="consent-item"><div><b>${i[1]} ${help(i[3])}</b><small>${i[2]}</small></div><label class="switch"><input type="checkbox" name="${i[0]}" ${state.consent[i[0]]?'checked':''}><span></span></label></div>`).join('')}</div><div class="consent-safety"><b>Bạn đang cho phép điều gì?</b><span>Đọc dữ liệu để điền hồ sơ, kiểm tra điều kiện và phát hiện quyền lợi. LifePath không gửi hồ sơ hoặc chia sẻ tiếp nếu chưa có xác nhận riêng.</span></div><div class="intake-actions"><button type="button" id="consent-prev" class="secondary-button">Quay lại</button><button class="primary-button">Đồng ý và tạo kế hoạch</button></div></form>`}
function analysis(m){return `<div class="intake-card analysis-box"><div class="analysis-ring"></div><h2>Đang xây dựng hành trình</h2><p class="intro">LifePath đang đối chiếu hoàn cảnh với quy tắc và nguồn chính thức.</p><ul class="analysis-log"><li class="done">Đã hiểu sự kiện: ${m.event}</li><li class="done">Đã áp dụng lựa chọn đồng ý dữ liệu</li><li class="done">Đang kiểm tra quyền lợi và thủ tục</li><li>Đang sắp xếp hành động theo quan hệ phụ thuộc</li></ul></div>`}
function bindIntake(){const pf=$('#profile-form');pf?.addEventListener('submit',e=>{e.preventDefault();new FormData(pf).forEach((v,k)=>state.profile[k]=v);state.step=2;save();renderIntake()});const cf=$('#consent-form');cf?.addEventListener('submit',e=>{e.preventDefault();['identity','employment','insurance','finance'].forEach(k=>state.consent[k]=!!cf.elements[k]?.checked);state.step=3;save();renderIntake()});$('#consent-prev')?.addEventListener('click',()=>{state.step=1;renderIntake()})}
function openApp(){const m=meta();$('#case-title').textContent=m.title;$('#case-code').textContent='LP-2026-'+String(Math.floor(100+Math.random()*899));$('#benefit-count').textContent=benefits().length;view('app-view');page('overview')}
function page(p){$$('.side-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const t={overview:['Hành trình của bạn','Tổng quan LifeCase'],benefits:['Entitlement Engine','Quyền lợi có thể liên quan'],journey:['Action Engine','Kế hoạch hành động'],documents:['Document Readiness','Kiểm tra giấy tờ'],rescue:['Rejection Rescue','Xử lý hồ sơ bị trả lại'],sources:['Trusted Knowledge','Nguồn chính thức']}[p];$('#page-eyebrow').textContent=t[0];$('#page-title').textContent=t[1];$('#page-content').innerHTML={overview:overview,benefits:benefitPage,journey:journeyPage,documents:documentPage,rescue:rescuePage,sources:sourcePage}[p]();bindPage(p)}
function taskHTML(t){return `<label class="task-item ${state.tasks[t.id]?'completed':''}"><input class="task-check" type="checkbox" data-task="${t.id}" ${state.tasks[t.id]?'checked':''}><span><b>${t.title} ${t.help?help(t.help):''}</b><small>${t.detail}</small></span><em class="due ${t.urgent?'urgent':''}">${t.due}</em></label>`}
function overview(){const ts=tasks(),bs=benefits(),done=ts.filter(t=>state.tasks[t.id]).length,ds=docs(),ready=ds.filter(d=>d.auto||state.documents[d.id]).length,score=readiness(),next=ts.find(t=>!state.tasks[t.id])||ts[ts.length-1],main=bs[0];if(state.journey!=='job')return `<div class="stats-grid"><div class="stat"><strong>${bs.length}</strong><span>quyền lợi có thể liên quan</span></div><div class="stat"><strong>${done}/${ts.length}</strong><span>hành động đã hoàn thành</span></div><div class="stat"><strong>${ready}/${ds.length}</strong><span>giấy tờ đã sẵn sàng</span></div></div><div class="dashboard-grid"><div class="panel"><h3>Tiến độ LifeCase</h3><div class="task-list">${ts.map(taskHTML).join('')}</div></div><div class="next-card"><small>HÀNH ĐỘNG TIẾP THEO</small><h3>${next.title}</h3><p>${next.detail}</p><button class="primary-button" data-go="journey">Mở kế hoạch</button></div></div>`;const deadline=plusMonths(state.profile.terminationDate,3),left=daysUntil(deadline);return `<section class="goal-card"><div><p class="eyebrow">MỤC TIÊU CHÍNH CỦA LIFECASE</p><h3>Hoàn tất hồ sơ trợ cấp thất nghiệp</h3><p>LifePath dẫn bạn từ thông tin ban đầu đến một bộ hồ sơ sẵn sàng nộp, sau đó theo dõi đến khi có kết quả.</p><div class="goal-meta"><span class="${left<=10?'critical':''}"><b>${left>=0?left:'0'} ngày</b> đến hạn dự kiến ${dateObjVN(deadline)}</span><span><b>${score}%</b> sẵn sàng</span><span><b>${done}/${ts.length}</b> bước hoàn tất</span></div></div><div class="goal-result"><small>NẾU ĐƯỢC PHÊ DUYỆT</small><strong>${main.summary}</strong><button class="outline-button" data-benefit="unemployment">Xem điều kiện và cách nhận</button></div></section><section class="outcome-section"><div class="section-heading"><div><p class="eyebrow">KẾT QUẢ LIFECASE</p><h3>LifePath đang giúp bạn đạt được gì?</h3></div>${help('Mỗi kết quả có hướng dẫn riêng. Một số quyền lợi phụ thuộc kết quả khác, vì vậy hệ thống sắp xếp theo thứ tự cần làm.')}</div><div class="outcome-list">${bs.map((b,i)=>`<button class="outcome-item" data-benefit="${b.id}"><span class="outcome-index">${i+1}</span><span><b>${b.title}</b><small>${b.result||b.summary}</small></span><em class="${b.status}">${{eligible:'Có khả năng phù hợp',review:'Cần kiểm tra thêm',unavailable:'Chưa phù hợp'}[b.status]}</em></button>`).join('')}</div></section><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h3>Lộ trình bắt buộc ${help('Làm lần lượt từ trên xuống. Chỉ đánh dấu khi bạn đã thực hiện hoặc đối chiếu xong bước đó.')}</h3><small>${done}/${ts.length} bước hoàn thành</small></div><button class="link-button" data-go="journey">Xem đủ 7 bước</button></div><div class="task-list">${ts.slice(0,4).map(taskHTML).join('')}</div></div><div><div class="next-card"><small>VIỆC CẦN LÀM NGAY</small><h3>${next.title} ${next.help?help(next.help):''}</h3><p>${next.detail}</p><button class="primary-button" data-go="journey">Bắt đầu bước này</button><div class="source-mini">Nguồn: ${next.source?SOURCES[next.source].agency:'Cần xác minh địa phương'}</div></div><div class="submission-card"><b>Nộp hồ sơ ở đâu?</b><p>Trung tâm Dịch vụ việc làm ${state.profile.location||'tại địa phương bạn chọn'}. Hãy mở trang thủ tục để kiểm tra địa chỉ và hình thức tiếp nhận hiện hành.</p><a class="outline-button" href="${SOURCES.unemployment.url}" target="_blank" rel="noreferrer">Mở thủ tục chính thức</a></div></div></div>`}
function benefitPage(){return `<div class="notice"><b>Đây là đánh giá sơ bộ, không phải quyết định hưởng quyền lợi.</b> LifePath cho biết kết quả có thể nhận và con đường để đạt được; cơ quan có thẩm quyền quyết định cuối cùng.</div><div class="benefit-list">${benefits().map(b=>`<article class="benefit-card"><div class="benefit-top"><div><h3>${b.title}</h3><p>${b.summary}</p></div><span class="status-pill ${b.status}">${{eligible:'Có khả năng đủ điều kiện',review:'Cần kiểm tra thêm',unavailable:'Chưa đủ điều kiện'}[b.status]}</span></div>${b.result?`<div class="benefit-result"><small>BẠN CÓ THỂ NHẬN ĐƯỢC</small><b>${b.result}</b></div>`:''}<div class="rule-meter"><i style="width:${Math.round(b.confidence*100)}%"></i></div><div class="reason-list">${b.reasons.map(r=>`<div class="reason ${r.ok?'pass':'unknown'}">${r.text}</div>`).join('')}</div>${b.dependency?`<p class="dependency"><b>Phụ thuộc:</b> ${b.dependency}</p>`:''}<div class="benefit-actions"><button class="primary-button" data-benefit="${b.id}">Xem hướng dẫn để nhận quyền lợi</button>${b.source?`<a class="outline-button" href="${SOURCES[b.source].url}" target="_blank" rel="noreferrer">Nguồn chính thức</a>`:''}</div></article>`).join('')}</div>`}
function journeyPage(){return `<div class="journey-intro"><div><p class="eyebrow">MỤC TIÊU</p><h3>Hoàn tất hồ sơ trợ cấp thất nghiệp và theo dõi đến kết quả</h3><p>Làm theo thứ tự từ bước 1 đến bước cuối. Dấu hỏi bên cạnh tiêu đề giải thích cách hoàn thành từng bước.</p></div><button class="outline-button" data-go="documents">Mở bộ giấy tờ</button></div><div class="journey-lanes">${tasks().map((t,i)=>`<article class="journey-step ${state.tasks[t.id]?'step-done':''}"><div class="journey-num">${String(i+1).padStart(2,'0')}</div><div><h3>${t.title} ${t.help?help(t.help):''}</h3><p>${t.detail}</p>${t.source?`<a class="step-source" href="${SOURCES[t.source].url}" target="_blank" rel="noreferrer">Kiểm tra hướng dẫn chính thức</a>`:''}<label class="complete-control"><input class="task-check" type="checkbox" data-task="${t.id}" ${state.tasks[t.id]?'checked':''}> ${state.tasks[t.id]?'Đã hoàn thành bước này':'Tôi đã hoàn thành bước này'}</label></div><span class="status-pill ${state.tasks[t.id]?'eligible':'review'}">${state.tasks[t.id]?'Hoàn thành':t.due}</span></article>`).join('')}</div><div class="success-destination"><b>Khi hoàn tất 7 bước</b><span>Bạn có một bộ hồ sơ đã kiểm tra, biết chính xác nơi nộp và có mã/phiếu hẹn để theo dõi đến khi nhận quyết định.</span></div>`}
function documentPage(){return `<div class="document-explainer"><div><p class="eyebrow">MỤC ĐÍCH CỦA BƯỚC NÀY</p><h3>Kiểm tra hồ sơ trước khi nộp</h3><p>Tải từng giấy tờ để LifePath lập báo cáo: tệp có đúng định dạng không, đã đủ thành phần chưa, và nội dung nào còn cần người dùng hoặc cơ quan xác minh.</p></div><a class="outline-button" href="${SOURCES.unemployment.url}" target="_blank" rel="noreferrer">Mở mẫu và yêu cầu chính thức</a></div><div class="dashboard-grid"><div class="document-grid">${docs().map(d=>{const file=state.documents[d.id],ok=d.auto||file;return `<article class="document-card ${ok?'uploaded':''}"><div class="document-title"><h3>${d.title}</h3>${help(d.auto?'Thông tin này được mô phỏng là đã đối chiếu từ nguồn dữ liệu bạn cho phép.':'Chọn PDF, PNG hoặc JPG dưới 8 MB. Prototype không gửi tệp lên máy chủ.')}</div><p>${d.desc}</p>${d.auto?`<div class="file-meta">Đã có từ nguồn dữ liệu được đồng ý</div><div class="doc-report"><span class="check-pass">✓ Nguồn dữ liệu đã kết nối</span><span class="check-review">! Cơ quan tiếp nhận quyết định giá trị pháp lý</span></div>`:`<label class="file-label" for="file-${d.id}">${ok?'Thay tệp':'Tải tệp để kiểm tra'}</label><input class="file-input" id="file-${d.id}" data-doc="${d.id}" type="file" accept=".pdf,.png,.jpg,.jpeg">${ok?`<div class="file-meta">${file.name} · ${file.size}</div><div class="doc-report"><span class="check-pass">✓ Có tệp, định dạng và kích thước phù hợp</span><span class="check-review">! Nội dung, chữ ký, ngày hiệu lực cần xác minh</span></div>`:`<div class="doc-empty">Chưa có tệp. LifePath chưa thể đánh dấu giấy tờ này là sẵn sàng.</div>`}`}</article>`}).join('')}</div><aside><div class="panel"><div class="panel-head"><h3>Mức sẵn sàng ${help('Điểm được tính từ giấy tờ đã có và các bước đã hoàn thành. Đây không phải tỷ lệ hồ sơ sẽ được phê duyệt.')}</h3></div><div class="readiness"><div class="score-ring" style="--score:${readiness()}%"><strong>${readiness()}%</strong></div><p><b>Prototype hiện kiểm tra:</b> sự hiện diện, định dạng và kích thước tệp.<br><br><b>Phiên bản triển khai sẽ kiểm tra thêm:</b> OCR, trường bắt buộc, ngày hiệu lực, chữ ký và mâu thuẫn với dữ liệu đã đồng ý.</p></div></div><div class="notice" style="margin-top:14px">Tệp demo chỉ được đọc cục bộ để hiển thị tên và kích thước. Kết quả không thay thế thẩm định pháp lý.</div></aside></div>`}
function rescuePage(){return `<div class="rescue-layout"><div class="rescue-box"><h3>Dán nội dung thông báo</h3><p class="intro">LifePath sẽ giải thích lý do và tạo hành động bổ sung.</p><textarea id="rejection-text" placeholder="Ví dụ: Đề nghị bổ sung quyết định chấm dứt hợp đồng...">${state.rescue?.text||''}</textarea><div class="intake-actions"><button id="demo-rejection" class="secondary-button">Dùng mẫu</button><button id="analyze-rejection" class="primary-button">Phân tích</button></div></div><div class="rescue-box">${state.rescue?rescueHTML():`<div class="empty-state"><div><b>Chưa có kết quả phân tích</b><p>Dán thông báo để bắt đầu.</p></div></div>`}</div></div>`}
function analyze(text){const l=text.toLowerCase(),a=[];if(/chấm dứt|thôi việc|hợp đồng/.test(l))a.push({title:'Thiếu giấy tờ chấm dứt việc làm',action:'Tải quyết định thôi việc hoặc tài liệu tương đương vào mục Giấy tờ.',doc:true});if(/căn cước|định danh|cccd/.test(l))a.push({title:'Cần bổ sung giấy tờ định danh',action:'Kiểm tra bản chụp đủ hai mặt, rõ và còn hiệu lực.',doc:true});if(/bảo hiểm|bhxh|bhtn/.test(l))a.push({title:'Cần xác minh dữ liệu bảo hiểm',action:'Đối chiếu quá trình tham gia và thời gian đóng BHTN.'});if(/mờ|không rõ|định dạng/.test(l))a.push({title:'Tệp chưa đạt chất lượng',action:'Chụp lại toàn bộ giấy tờ trong điều kiện đủ sáng hoặc tải PDF rõ nét.'});if(!a.length)a.push({title:'Chưa xác định yêu cầu cụ thể',action:'Hãy yêu cầu cơ quan tiếp nhận nêu rõ lý do và giấy tờ cần bổ sung.'});return a}
function sampleRejection(){if(state.journey==='baby')return'Hồ sơ cần bổ sung giấy chứng sinh và kiểm tra lại thông tin nơi cư trú. Bản chụp căn cước hiện tại không rõ thông tin.';if(state.journey==='business')return'Hồ sơ cần bổ sung thông tin địa điểm kinh doanh và tài liệu về an toàn thực phẩm. Bản sao căn cước hiện tại không rõ thông tin.';return'Hồ sơ chưa hợp lệ. Đề nghị bổ sung quyết định chấm dứt hợp đồng lao động và bản sao căn cước còn hiệu lực. Bản chụp hiện tại không rõ thông tin.'}
function rescueHTML(){return `<h3>LifePath đã giải thích</h3><p class="intro">Phát hiện ${state.rescue.findings.length} nội dung cần chú ý.</p><div class="rescue-findings">${state.rescue.findings.map(f=>`<div class="finding"><b>${f.title}</b><span>${f.action}</span>${f.doc?`<button class="link-button" data-go="documents">Mở mục Giấy tờ</button>`:''}</div>`).join('')}</div><div class="notice" style="margin-top:16px">Kết quả hỗ trợ diễn giải, không thay thế ý kiến của cơ quan có thẩm quyền.</div>`}
function sourcePage(){const used=new Set();benefits().forEach(b=>b.source&&used.add(b.source));tasks().forEach(t=>t.source&&used.add(t.source));return `<div class="notice">Mỗi kết quả phải truy nguyên được về nguồn. Ngày cập nhật giúp cảnh báo khi quy định có thể thay đổi.</div><div class="source-list">${[...used].map(k=>{const s=SOURCES[k];return `<article class="source-card"><b>${s.title}</b><small>${s.agency} · Cập nhật: ${s.updated}</small><a href="${s.url}" target="_blank" rel="noreferrer">${s.url}</a></article>`}).join('')}</div>`}
function bindPage(p){$$('[data-go]').forEach(b=>b.onclick=()=>page(b.dataset.go));$$('[data-task]').forEach(c=>c.onchange=()=>{state.tasks[c.dataset.task]=c.checked;save();page(p);toast(c.checked?'Đã cập nhật tiến độ':'Đã hoàn tác')});$$('[data-benefit]').forEach(b=>b.onclick=()=>detail(b.dataset.benefit));$$('[data-doc]').forEach(i=>i.onchange=()=>{const f=i.files[0];if(!f)return;if(f.size>8*1024*1024)return toast('Tệp vượt quá 8 MB');const ext=f.name.split('.').pop().toLowerCase();if(!['pdf','png','jpg','jpeg'].includes(ext))return toast('Chỉ hỗ trợ PDF, PNG hoặc JPG');state.documents[i.dataset.doc]={name:f.name,size:`${(f.size/1024).toFixed(0)} KB`,format:ext.toUpperCase(),contentCheck:'pending'};save();page('documents');toast('Định dạng đạt yêu cầu; nội dung vẫn cần xác minh')});$('#demo-rejection')?.addEventListener('click',()=>{$('#rejection-text').value=sampleRejection()});$('#analyze-rejection')?.addEventListener('click',()=>{const text=$('#rejection-text').value.trim();if(!text)return toast('Hãy nhập nội dung thông báo');state.rescue={text,findings:analyze(text)};save();page('rescue');toast('Đã tạo hướng xử lý')})}
function detail(id){const b=benefits().find(x=>x.id===id),s=b.source?SOURCES[b.source]:null,requirements=b.requirements||['Mở nguồn chính thức để kiểm tra thành phần hồ sơ hiện hành'];$('#detail-title').textContent=b.title;$('#detail-content').innerHTML=`<div class="detail-status"><span class="status-pill ${b.status}">${{eligible:'Có khả năng phù hợp',review:'Cần kiểm tra thêm',unavailable:'Chưa đủ điều kiện'}[b.status]}</span><p>${b.summary}</p></div>${b.result?`<section class="detail-section highlight"><small>BẠN CÓ THỂ NHẬN ĐƯỢC</small><b>${b.result}</b></section>`:''}<section class="detail-section"><h4>Điều kiện đang được đối chiếu</h4><div class="reason-list">${b.reasons.map(r=>`<div class="reason ${r.ok?'pass':'unknown'}">${r.text}</div>`).join('')}</div></section><section class="detail-section"><h4>Cần chuẩn bị gì?</h4><ol>${requirements.map(x=>`<li>${x}</li>`).join('')}</ol></section>${b.submission?`<section class="detail-section"><h4>Nộp hoặc thực hiện ở đâu?</h4><p>${b.submission}</p></section>`:''}${b.dependency?`<section class="detail-section"><h4>Quyền lợi này phụ thuộc gì?</h4><p>${b.dependency}</p></section>`:''}<section class="detail-next"><small>BƯỚC TIẾP THEO</small><b>${b.next||'Mở kế hoạch hành động để tiếp tục'}</b><button class="primary-button" data-modal-go="${id==='unemployment'?'journey':'benefits'}">${id==='unemployment'?'Mở kế hoạch 7 bước':'Quay lại danh sách quyền lợi'}</button></section>${s?`<section class="detail-section"><h4>Nguồn kiểm chứng</h4><p><a href="${s.url}" target="_blank" rel="noreferrer">${s.title} · ${s.agency}</a></p></section>`:''}<p class="legal-note">LifePath hỗ trợ chuẩn bị và giải thích. Quyết định cuối cùng thuộc cơ quan có thẩm quyền.</p>`;$('#detail-dialog').showModal();$('[data-modal-go]')?.addEventListener('click',e=>{$('#detail-dialog').close();page(e.currentTarget.dataset.modalGo)})}
function start(prompt){state=cloneBase();state.prompt=prompt;state.journey=detect(prompt);state.step=1;save();view('intake-view');renderIntake()}
$('#event-form').onsubmit=e=>{e.preventDefault();start($('#event-input').value.trim())};$$('.example-chip').forEach(b=>b.onclick=()=>{$('#event-input').value=b.dataset.example;start(b.dataset.example)});$('#intake-back').onclick=()=>{if(state.step>1){state.step--;renderIntake()}else view('start-view')};$$('.side-nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#new-case-button').onclick=()=>view('start-view');$('#brand-home').onclick=()=>view('start-view');$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#profile-button').onclick=()=>toast('Hồ sơ mẫu: Nguyễn Lan · Đà Nẵng');$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#clear-data-button').onclick=()=>{localStorage.removeItem(KEY);state=cloneBase();$('#privacy-dialog').close();view('start-view');toast('Đã xóa dữ liệu demo')};
if(state.createdAt)openApp();else view('start-view');
